import heapq

class Node:
    def __init__(self, x, y, cost, heuristic):
        self.x = x
        self.y = y
        self.cost = cost
        self.heuristic = heuristic
        self.total_cost = cost + heuristic

    def __lt__(self, other):
        return self.total_cost < other.total_cost

def heuristic(node, goal):
    """Manhattan distance heuristic"""
    return abs(node.x - goal.x) + abs(node.y - goal.y)

def in_bounds(node, grid_size):
    """Check if the node is within bounds"""
    return 0 <= node.x < grid_size[0] and 0 <= node.y < grid_size[1]

def get_neighbors(node, grid, obstacles):
    """Get the neighbors of the current node, avoiding obstacles"""
    neighbors = []
    for dx, dy in [(0, 1), (1, 0), (0, -1), (-1, 0)]:
        neighbor_x, neighbor_y = node.x + dx, node.y + dy
        if in_bounds((neighbor_x, neighbor_y), grid.size) and not grid[neighbor_x, neighbor_y] and not obstacles[(neighbor_x, neighbor_y)]:
            neighbors.append((neighbor_x, neighbor_y))
    return neighbors

def a_star_search(grid, start, goal, obstacles):
    """A* search algorithm"""
    start_node = Node(start[0], start[1], 0, heuristic(start, goal))
    open_set = [start_node]
    closed_set = set()

    while open_set:
        current_node = heapq.heappop(open_set)

        if (current_node.x, current_node.y) == goal:
            return current_node

        closed_set.add((current_node.x, current_node.y))

        for neighbor in get_neighbors(current_node, grid, obstacles):
            neighbor_node = Node(neighbor[0], neighbor[1], current_node.cost + 1, heuristic(neighbor, goal))
            if neighbor_node not in closed_set:
                heapq.heappush(open_set, neighbor_node)

    return None  # No path found

