### Depth-First Search (DFS)

DFS is a simple algorithm that explores as far as possible along each branch before backtracking. It can be useful in scenarios where a path to the goal is desired, or when the goal is known to be at a certain depth in the search space.

```python
class Graph:
    def __init__(self, graph_dict=None):
        if graph_dict is None:
            graph_dict = {}
        self.graph_dict = graph_dict

    def add_vertex(self, vertex):
        if vertex not in self.graph_dict:
            self.graph_dict[vertex] = []

    def add_edge(self, vertex1, vertex2):
        if vertex1 in self.graph_dict:
            self.graph_dict[vertex1].append(vertex2)
        else:
            self.graph_dict[vertex1] = [vertex2]
        if vertex2 in self.graph_dict:
            self.graph_dict[vertex2].append(vertex1)
        else:
            self.graph_dict[vertex2] = [vertex1]

    def dfs(self, start_vertex, target='end'):
        visited = set()
        stack = [start_vertex]

        while stack:
            vertex = stack.pop()
            if vertex == target:
                return f"Target {target} found at {vertex}"
            if vertex not in visited:
                visited.add(vertex)
                stack.extend(self.graph_dict[vertex])
        return f"Target {target} not found"

