import heapq

class Node:
    def __init__(self, x, y, g_cost, h_cost, parent):
        self.x = x
        self.y = y
        self.g_cost = g_cost  # Cost from start node to current node
        self.h_cost = h_cost  # Heuristic cost from current node to goal
        self.parent = parent

    def __lt__(self, other):
        return self.g_cost + self.h_cost < other.g_cost + other.h_cost

    def __eq__(self, other):
        return (self.x, self.y) == (other.x, other.y)

def astar_search(grid, start, goal):
    rows, cols = len(grid), len(grid[0])
    open_set = []
    heapq.heappush(open_set, Node(start[0], start[1], 0, manhattan_distance(start, goal), None))
    came_from = {}
    cost_so_far = {Node(start[0], start[1], 0, 0, None): 0}

    while open_set:
        current_node = heapq.heappop(open_set)

        if current_node.x == goal[0] and current_node.y == goal[1]:
            path = []
            while current_node:
                path.append((current_node.x, current_node.y))
                current_node = current_node.parent
            return path[::-1]

        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
